import { BrowserModule } from '@angular/platform-browser';
import { NgModule } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { AppComponent } from './app.component';
import { TableComponent } from './MainApp/Profile-viewer/table/table.component';
import { TableRowComponent } from './MainApp/Profile-viewer/table-row/table-row.component';
import {  TableRowMixedComponent} from './MainApp/Profile-viewer/table-row-mixed/table-row-mixed.component';
import { HttpClientModule } from '@angular/common/http';
import { RouterModule } from '@angular/router';
import { AdventureTimeService } from './Shared/services/adventure-time.service';
import { TableRowIncorrectComponent } from './MainApp/Profile-viewer/table-row-incorrect/table-row-incorrect.component';
import { FileuploadComponent } from './MainApp/file-upload/file-upload.component';
import { SearchWordComponent } from './search-word/search-word.component';
import { HomeComponent } from './AddOns/home/home.component';
import {  BlobuploadComponent} from './blobupload/blobupload.component'

import { NguiInViewComponent } from './POC-Components/ngui-in-view/ngui-in-view.component';
import { VideoplayerComponent } from './MainApp/video-viewer/videoplayer.component';
import { ImageViewerComponent } from './image-viewer/image-viewer.component'
import { PreviewComponent } from './POC-Components/preview/preview.component';
import { ShareComponent } from './POC-Components/share/share.component';
import { NavMenuComponent } from './POC-Components/nav-menu/nav-menu.component';
import { AuthService } from './Shared/services/auth.service';
import { ProfileComponent } from './Shared/profile/profile.component';
// import { MeetingsComponent } from './meetings/meetings.component'
// import { DyteComponentsModule } from '@dytesdk/angular-ui-kit';
// import { ChatroomsComponent} from './chatrooms/chatrooms.component'
import { AppstoreComponent } from './MainApp/appstore/appstore.component'
import { ContentuploadComponent} from './AddOns/contentupload/contentupload.component'
import {  GraphQLModule } from './graphql.module'


@NgModule({
    declarations: [
        AppComponent,        
        TableComponent,
        TableRowComponent,
        TableRowIncorrectComponent,
        TableRowMixedComponent,
        FileuploadComponent,
        // SearchWordComponent,
        HomeComponent,        
        NguiInViewComponent,
        VideoplayerComponent,
        ImageViewerComponent,
        PreviewComponent,
        ShareComponent,
        NavMenuComponent,
        
        BlobuploadComponent,
        ProfileComponent,
        // MeetingsComponent,
        // ChatroomsComponent,
        AppstoreComponent,
        ContentuploadComponent,
        

    ],
    imports: [

        BrowserModule,
        FormsModule,
    
        ReactiveFormsModule,
        SearchWordComponent,
        HttpClientModule,
        RouterModule.forRoot([{
            path: 'mysite/:id',component: AppComponent
        },
            
        ]),
        GraphQLModule, 
        
            
    ],
	providers: [AdventureTimeService , AuthService

        
    ],
    bootstrap: [AppComponent]
})
export class AppModule { }
